const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds and shadows in Landsat 8 Collection 2 imagery.
function maskL8sr(image) {
  // Bits 3 (cloud shadow) and 5 (cloud) are set.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  // Get the pixel QA band.
  const qa = image.select('QA_PIXEL');
  // Both flags should be set to zero, indicating clear conditions.
  let mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  return image.updateMask(mask);
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([14.426, 40.821]).buffer(1000); // Point for Mt. Vesuvius cone, 1km buffer
  const dateStart = '2022-01-02';
  const dateEnd = '2022-01-03';

  // 2. Data Acquisition & Check
  const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(dateStart, dateEnd);

  const collectionSize = l8Collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No Landsat 8 images found for Mount Vesuvius on January 2, 2022.");
